#if PROFILE_UNLOCK_TESTING
using System.IO;
using System.IO.Compression;
using System.Text.Json;

namespace FH6LocalCryptoTool;

// Installed FH6 definitions and English strings, inspected 2026-10-14.
// Generated from strictly round-tripped definitions; no save/account data.
internal static class BadgeCatalog
{
    internal sealed record Objective(ulong Id, uint Target, bool Exact);
    internal sealed record Badge(uint Id, ulong SaveId, ulong LinkedId, uint Version, string Name, string Description, string Category, Objective[] Objectives);
    internal static IReadOnlyList<Badge> Items { get; } = Array.AsReadOnly(Decode());
    static Badge[] Decode()
    {
        using var input = new MemoryStream(Convert.FromBase64String(Encoded));
        using var gzip = new GZipStream(input, CompressionMode.Decompress);
        return JsonSerializer.Deserialize<Badge[]>(gzip) ?? throw new InvalidDataException("Inventory catalog is missing.");
    }
    const string Encoded = "";
}
#endif

